// Table of switchable game patches, generated by tools/game_patches.py into
// generated/patches/game_patch_table.cpp (or empty, game_patch_table_empty.cpp,
// when that has not been run). Used by game_patches.cpp.
#pragma once

#include <cstdint>

class PS2Runtime;
struct R5900Context;

namespace kh2patches
{
using PatchFunction = void (*)(uint8_t *, R5900Context *, PS2Runtime *);

// A recompiled copy of a game function with the patch's instructions in it.
struct CodeVariant
{
    uint32_t address; // 0 ends the list
    PatchFunction function;
};

// A memory write repeated every frame.
struct DataWrite
{
    uint32_t address; // 0 ends the list
    uint32_t value;
    int bits; // 8, 16 or 32
};

struct GamePatch
{
    const char *name; // nullptr ends the table
    const char *description;
    const char *author;
    float aspect; // display aspect the patch renders for, 0 = unchanged
    const CodeVariant *code;
    const DataWrite *data;
};

extern const GamePatch kGamePatches[];
} // namespace kh2patches
